const c=$input.first().json;
if (!c || !c.source || !Array.isArray(c.source.leads) || c.source.leads.length!==10) throw new Error('Expected ten source leads');
if (typeof c.run_id!=='string' || !c.run_id || typeof c.source.source_name!=='string' || !c.source.source_name) throw new Error('Invalid context');
if (!c.environment || typeof c.environment.base_url!=='string' || !/^https?:\/\//.test(c.environment.base_url)) throw new Error('Invalid base URL');
if (typeof c.ui_origin!=='string' || !/^http:\/\/(127\.0\.0\.1|localhost):\d+$/.test(c.ui_origin)) throw new Error('Invalid UI origin');
if (typeof c.now!=='string' || !Number.isFinite(Date.parse(c.now))) throw new Error('Invalid supplied now');
const ids=new Set(),emails=new Set();
return c.source.leads.map((lead,i)=>{
 if (!lead || typeof lead.lead_id!=='string' || !lead.lead_id || typeof lead.email!=='string' || !lead.email.trim() ||
 typeof lead.first_name!=='string' || !lead.first_name.trim() || typeof lead.last_name!=='string' || !lead.last_name.trim() ||
 typeof lead.company!=='string' || typeof lead.discovery_context!=='string' || typeof lead.job_title!=='string' ||
 typeof lead.fixture_last_customer_message_utc!=='string' || typeof lead.fixture_last_customer_message_excerpt!=='string') throw new Error('Invalid lead '+i);
 const email=lead.email.trim().toLowerCase();
 if (ids.has(lead.lead_id)||emails.has(email)) throw new Error('Duplicate source identity');
 ids.add(lead.lead_id);emails.add(email);
 const timed=!!lead.fixture_last_customer_message_utc.trim(),bodied=!!lead.fixture_last_customer_message_excerpt.trim();
 if (timed!==bodied || (timed&&!Number.isFinite(Date.parse(lead.fixture_last_customer_message_utc)))) throw new Error('Invalid fixture '+lead.lead_id);
 return {json:{lead,source_name:c.source.source_name,now:c.now},pairedItem:0};
});

const s=$('Loop Leads').item.json, rows=JSON.parse($input.first().json.body);
if (!Array.isArray(rows)) throw new Error('Contact search shape');
const exact=rows.filter(x=>x&&typeof x.email==='string'&&x.email.toLowerCase()===s.lead.email.trim().toLowerCase());
if (exact.length>1) throw new Error('Duplicate CRM email');
const old=exact[0]||null;
if (old&&(!old.contact_id||typeof old.contact_id!=='string')) throw new Error('Missing contact ID');
return [{json:{...s,original_contact:old,contact_created:!old,method:old?'GET':'POST',
path:old?'/api/contacts/'+encodeURIComponent(old.contact_id):'/api/contacts',
body:old?null:{email:s.lead.email.trim(),first_name:s.lead.first_name.trim(),last_name:s.lead.last_name.trim()}},pairedItem:0}];

const s=$('Plan Contact').item.json,r=JSON.parse($input.first().json.body),o=s.original_contact;
if (!r||typeof r.contact_id!=='string'||!r.contact_id||typeof r.email!=='string'||r.email.toLowerCase()!==s.lead.email.trim().toLowerCase()) throw new Error('Contact resolution mismatch');
if (o) {
 if (r.contact_id!==o.contact_id||r.lifecycle_stage!==o.lifecycle_stage||r.company_id!==o.company_id||
 r.company_name!==o.company_name||r.first_name!==o.first_name||r.last_name!==o.last_name) throw new Error('Existing identity changed');
} else if (r.first_name!==s.lead.first_name.trim()||r.last_name!==s.lead.last_name.trim()) throw new Error('Created name mismatch');
const change=r.job_title!==s.lead.job_title.trim();
return [{json:{...s,contact:r,contact_id:r.contact_id,title_updated:change,method:change?'PATCH':'GET',
path:'/api/contacts/'+encodeURIComponent(r.contact_id),body:change?{job_title:s.lead.job_title.trim()}:null},pairedItem:0}];

const s=$('Plan Job Title').item.json,r=JSON.parse($input.first().json.body),o=s.original_contact;
if (!r||r.contact_id!==s.contact_id||typeof r.email!=='string'||r.email.toLowerCase()!==s.lead.email.trim().toLowerCase()||
 r.job_title!==s.lead.job_title.trim()||r.first_name!==s.contact.first_name||r.last_name!==s.contact.last_name||
 r.lifecycle_stage!==s.contact.lifecycle_stage||r.company_id!==s.contact.company_id||r.company_name!==s.contact.company_name) throw new Error('Contact read-back mismatch');
if (o&&(r.lifecycle_stage!==o.lifecycle_stage||r.company_id!==o.company_id)) throw new Error('CRM association changed');
return [{json:{...s,contact:r},pairedItem:0}];

const s=$('Verify Contact').item.json,activities=JSON.parse($input.first().json.body);
if (!Array.isArray(activities)) throw new Error('Activities shape');
const note='Source '+s.source_name+' / '+s.lead.lead_id+'; company: '+s.lead.company+'; discovery context: '+s.lead.discovery_context;
const existing=activities.filter(a=>a&&a.kind==='note'&&a.body===note);
if (existing.length>1) throw new Error('Duplicate source note');
const create=!existing.length;
return [{json:{...s,activities,note_text:note,note_created:create,method:create?'POST':'GET',
path:'/api/contacts/'+encodeURIComponent(s.contact_id)+(create?'/notes':'/activities'),
body:create?{body:note,include_company:false}:null},pairedItem:0}];

const s=$('Plan Note').item.json,r=JSON.parse($input.first().json.body);
const note=s.note_created?r:(Array.isArray(r)?r.find(a=>a&&a.kind==='note'&&a.body===s.note_text):null);
if (!note||note.kind!=='note'||note.contact_id!==s.contact_id||note.body!==s.note_text||typeof note.activity_id!=='string') throw new Error('Note verification failed');
return [{json:{...s,note_id:note.activity_id},pairedItem:0}];

const s=$input.first().json,l=s.lead,wanted=!!l.fixture_last_customer_message_utc.trim(),sourceId=s.source_name+':'+l.lead_id+':customer-message';
const present=s.activities.filter(a=>a&&a.kind==='message'&&a.source_id===sourceId);
if (present.length>1) throw new Error('Duplicate fixture messages');
if (present.length&&(!wanted||present[0].body!==l.fixture_last_customer_message_excerpt||
 Date.parse(present[0].received_at)!==Date.parse(l.fixture_last_customer_message_utc)||present[0].direction!=='inbound')) throw new Error('Fixture message mismatch');
const create=wanted&&!present.length;
return [{json:{...s,message_created:create,fixture_source_id:sourceId,method:create?'POST':'GET',
path:'/api/contacts/'+encodeURIComponent(s.contact_id)+'/messages',
body:create?{body:l.fixture_last_customer_message_excerpt,received_at:l.fixture_last_customer_message_utc,source_id:sourceId}:null},pairedItem:0}];

const s=$('Plan Message').item.json,r=JSON.parse($input.first().json.body);
if (s.message_created&&(!r||r.kind!=='message'||r.direction!=='inbound'||r.contact_id!==s.contact_id||
 r.source_id!==s.fixture_source_id||r.body!==s.lead.fixture_last_customer_message_excerpt||
 Date.parse(r.received_at)!==Date.parse(s.lead.fixture_last_customer_message_utc)||typeof r.activity_id!=='string')) throw new Error('Fixture message creation mismatch');
if (!s.message_created&&!Array.isArray(r)) throw new Error('Message read shape');
return [{json:{...s,fixture_message_id:s.message_created?r.activity_id:(r.find(m=>m&&m.source_id===s.fixture_source_id)||{}).activity_id||null},pairedItem:0}];

const s=$('Verify Message').item.json,messages=JSON.parse($input.first().json.body);
if (!Array.isArray(messages)) throw new Error('CRM messages shape');
for (const m of messages) if (!m||m.kind!=='message'||m.direction!=='inbound'||m.contact_id!==s.contact_id||
 !Number.isFinite(Date.parse(m.received_at))||typeof m.activity_id!=='string') throw new Error('Invalid inbound message');
if (s.lead.fixture_last_customer_message_utc.trim()) {
 const f=messages.find(m=>m.source_id===s.fixture_source_id);
 if (!f||f.body!==s.lead.fixture_last_customer_message_excerpt||
 Date.parse(f.received_at)!==Date.parse(s.lead.fixture_last_customer_message_utc)) throw new Error('Fixture absent from CRM messages');
}
messages.sort((a,b)=>Date.parse(b.received_at)-Date.parse(a.received_at));
const last=messages[0]||null,overdue=!!last&&Date.parse(s.now)-Date.parse(last.received_at)>48*60*60*1000;
return [{json:{...s,last_message:last?{activity_id:last.activity_id,source_id:last.source_id||null,received_at:last.received_at,body:last.body}:null,
 follow_up_due:overdue,follow_up_reason:!last?'no_inbound_message':overdue?'over_48_hours':'recent_or_exactly_48_hours'},pairedItem:0}];

const s=$('Evaluate Recency').item.json,activities=JSON.parse($input.first().json.body);
if (!Array.isArray(activities)) throw new Error('Current activities shape');
const last=s.last_message,key=last?'followup:'+s.lead.lead_id+':'+last.activity_id:null;
const existing=key?activities.filter(a=>a&&a.kind==='task'&&a.idempotency_key===key):[];
if (existing.length>1) throw new Error('Duplicate follow-up tasks');
const create=s.follow_up_due&&!existing.length;
const topic=last?last.body.trim().replace(/\s+/g,' ').slice(0,120):'';
const name=s.contact.first_name,company=s.contact.company_name||s.lead.company;
const title=create?'Follow up with '+name+' about '+topic:null;
const body=create?'Call '+name+(company?' at '+company:'')+' about their latest customer message: "'+topic+'". Context: '+s.lead.discovery_context:null;
return [{json:{...s,task_created:create,task_key:key,existing_task_id:existing[0]?.activity_id||null,
 method:create?'POST':'GET',path:'/api/contacts/'+encodeURIComponent(s.contact_id)+(create?'/tasks':'/activities'),
 body:create?{title,body,due_date:s.now.slice(0,10),due_time:'09:00',task_type:'To-do',priority:'Medium',include_company:false,idempotency_key:key}:null},pairedItem:0}];

const s=$('Plan Follow Up').item.json,activities=JSON.parse($input.first().json.body);
if (!Array.isArray(activities)) throw new Error('Final activities shape');
const notes=activities.filter(a=>a&&a.kind==='note'&&a.body===s.note_text);
if (notes.length!==1||notes[0].activity_id!==s.note_id) throw new Error('Final note read-back mismatch');
let taskId=null;
if (s.follow_up_due) {
 const tasks=activities.filter(a=>a&&a.kind==='task'&&a.idempotency_key===s.task_key);
 if (tasks.length!==1||typeof tasks[0].activity_id!=='string') throw new Error('Follow-up read-back mismatch');
 taskId=tasks[0].activity_id;
 if (s.task_created&&(tasks[0].title!==s.body.title||tasks[0].body!==s.body.body)) throw new Error('Follow-up content mismatch');
 if (!s.task_created&&taskId!==s.existing_task_id) throw new Error('Existing task identity changed');
}
return [{json:{lead_id:s.lead.lead_id,email:s.contact.email,contact_id:s.contact_id,first_name:s.contact.first_name,
 job_title:s.contact.job_title,lifecycle_stage:s.contact.lifecycle_stage,company_id:s.contact.company_id,
 contact_created:s.contact_created,title_updated:s.title_updated,note_id:s.note_id,note_created:s.note_created,
 fixture_message_id:s.fixture_message_id,message_created:s.message_created,last_inbound_message:s.last_message,
 follow_up_reason:s.follow_up_reason,follow_up_due:s.follow_up_due,follow_up_task_id:taskId,task_created:s.task_created},pairedItem:0}];

const c=$('Context').first().json,rows=$input.all().map(x=>x.json);
if (rows.length!==10||new Set(rows.map(x=>x.lead_id)).size!==10||new Set(rows.map(x=>x.contact_id)).size!==10) throw new Error('Incomplete lead processing');
const trace=rows.map(r=>({timestamp:c.now,kind:'lead_processed',data:{
 lead_id:r.lead_id,contact_id:r.contact_id,contact_created:r.contact_created,title_updated:r.title_updated,
 note_created:r.note_created,message_created:r.message_created,last_inbound_message_id:r.last_inbound_message?.activity_id||null,
 follow_up_reason:r.follow_up_reason,follow_up_task_id:r.follow_up_task_id,task_created:r.task_created}}));
return [{json:{protocol_version:'1.0',run_id:c.run_id,status:'completed',
 final_answer:'Processed ten fictional leads, verified CRM records, and scheduled eligible follow-ups without duplicate writes.',
 artifacts:[{name:'lead-import-follow-up.json',media_type:'application/json',
 content:JSON.stringify({source_name:c.source.source_name,now:c.now,leads:rows})}],trace}}];
